//! Recurrence rules (`rr`). Recurring to-dos use a template (carries `rr`,
//! hidden from lists) plus visible instances whose `rt` points at the template.
//! New instances are generated by the official Things apps, not by Tings 3.

use chrono::{Datelike, Duration, Months, NaiveDate};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};

use crate::dates;

pub const UNIT_DAY: i64 = 16;
pub const UNIT_WEEK: i64 = 256;
pub const UNIT_MONTH: i64 = 8;
pub const UNIT_YEAR: i64 = 4;
/// `ed` value meaning "never ends" (year 4001).
pub const NEVER_ENDS: i64 = 64092211200;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum RepeatUnit {
    Day,
    Week,
    Month,
    Year,
}

/// A simple repeat rule that the UI can create.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RepeatSpec {
    pub unit: RepeatUnit,
    #[serde(default = "one")]
    pub interval: u32,
    /// 0 = Sunday … 6 = Saturday (weekly rules).
    #[serde(default)]
    pub weekdays: Vec<u8>,
    /// 1…31, or -1 for the last day (monthly rules).
    #[serde(default)]
    pub month_day: Option<i32>,
}

fn one() -> u32 {
    1
}

/// Builds a fixed-schedule, never-ending `rr` value in the shape used by the
/// reference MCP (`rrv` 4).
pub fn build_rule(spec: &RepeatSpec, reference: NaiveDate) -> Result<Value, String> {
    if spec.interval == 0 || spec.interval > 365 {
        return Err("repeat interval must be between 1 and 365".into());
    }
    let ref_ts = dates::date_to_wire(reference);
    let (fu, of) = match spec.unit {
        RepeatUnit::Day => (UNIT_DAY, json!([{ "dy": 0 }])),
        RepeatUnit::Week => {
            let mut days = spec.weekdays.clone();
            if days.is_empty() {
                days.push(reference.weekday().num_days_from_sunday() as u8);
            }
            days.sort_unstable();
            days.dedup();
            if days.iter().any(|d| *d > 6) {
                return Err("weekday must be 0 (Sunday) to 6 (Saturday)".into());
            }
            (UNIT_WEEK, Value::Array(days.iter().map(|d| json!({ "wd": d })).collect()))
        }
        RepeatUnit::Month => {
            let day = spec.month_day.unwrap_or(reference.day() as i32);
            let dy = match day {
                -1 => -1,
                1..=31 => day - 1,
                _ => return Err("month day must be 1–31 or -1 (last day)".into()),
            };
            (UNIT_MONTH, json!([{ "dy": dy }]))
        }
        RepeatUnit::Year => (UNIT_YEAR, json!([{ "dy": reference.day0(), "mo": reference.month0() }])),
    };
    Ok(json!({
        "rrv": 4, "tp": 0, "rc": 0, "ts": 0, "ed": NEVER_ENDS,
        "ia": ref_ts, "sr": ref_ts, "fu": fu, "fa": spec.interval, "of": of,
    }))
}

fn weekday_name(wd: i64) -> &'static str {
    ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].get(wd as usize).copied().unwrap_or("?")
}

fn ordinal(n: i64) -> String {
    let suffix = match (n % 10, n % 100) {
        (1, r) if r != 11 => "st",
        (2, r) if r != 12 => "nd",
        (3, r) if r != 13 => "rd",
        _ => "th",
    };
    format!("{n}{suffix}")
}

const MONTHS: [&str; 12] = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

/// Human-readable summary such as "Every 2 weeks on Mon, Wed".
pub fn describe(rr: &Value) -> String {
    let fu = rr.get("fu").and_then(Value::as_i64).unwrap_or(0);
    let fa = rr.get("fa").and_then(Value::as_i64).unwrap_or(1).max(1);
    let of: Vec<Value> = rr.get("of").and_then(Value::as_array).cloned().unwrap_or_default();
    let after_completion = rr.get("tp").and_then(Value::as_i64) == Some(1);
    let (singular, plural, adverb) = match fu {
        UNIT_DAY => ("day", "days", "Daily"),
        UNIT_WEEK => ("week", "weeks", "Weekly"),
        UNIT_MONTH => ("month", "months", "Monthly"),
        UNIT_YEAR => ("year", "years", "Yearly"),
        _ => return "Repeating".into(),
    };
    let mut s = if after_completion {
        if fa == 1 {
            format!("1 {singular} after completion")
        } else {
            format!("{fa} {plural} after completion")
        }
    } else if fa == 1 {
        adverb.to_string()
    } else {
        format!("Every {fa} {plural}")
    };
    if !after_completion {
        let detail: Vec<String> = of
            .iter()
            .filter_map(|o| {
                let wd = o.get("wd").and_then(Value::as_i64);
                let wdo = o.get("wdo").and_then(Value::as_i64);
                let dy = o.get("dy").and_then(Value::as_i64);
                let mo = o.get("mo").and_then(Value::as_i64);
                match (fu, wd, wdo, dy) {
                    (UNIT_WEEK, Some(wd), _, _) => Some(weekday_name(wd).to_string()),
                    (UNIT_MONTH | UNIT_YEAR, Some(wd), Some(-1), _) => Some(format!("last {}", weekday_name(wd))),
                    (UNIT_MONTH | UNIT_YEAR, Some(wd), Some(n), _) => Some(format!("{} {}", ordinal(n), weekday_name(wd))),
                    (UNIT_MONTH, _, _, Some(-1)) => Some("the last day".into()),
                    (UNIT_MONTH, _, _, Some(d)) => Some(format!("the {}", ordinal(d + 1))),
                    (UNIT_YEAR, _, _, Some(d)) => {
                        let m = mo.and_then(|m| MONTHS.get(m as usize)).copied().unwrap_or("");
                        Some(format!("{m} {}", d + 1).trim().to_string())
                    }
                    _ => None,
                }
            })
            .collect();
        if !detail.is_empty() {
            s.push_str(" on ");
            s.push_str(&detail.join(", "));
        }
    }
    let count = rr.get("rc").and_then(Value::as_i64).unwrap_or(0);
    let end = rr.get("ed").and_then(Value::as_f64);
    if count > 0 {
        s.push_str(&format!(", {count} times"));
    } else if let Some(end) = end.filter(|e| (*e as i64) < NEVER_ENDS) {
        if let Some(d) = dates::wire_to_date(end) {
            s.push_str(&format!(", until {}", dates::format_ymd(d)));
        }
    }
    s
}

/// Next occurrence strictly after `current` (mirrors the SDK's
/// `NextOccurrenceAfter`). Used to date the template when creating a rule.
pub fn next_after(rr: &Value, current: NaiveDate) -> Option<NaiveDate> {
    let fu = rr.get("fu")?.as_i64()?;
    let fa = rr.get("fa").and_then(Value::as_i64).unwrap_or(1).max(1);
    match fu {
        UNIT_DAY => current.checked_add_signed(Duration::days(fa)),
        UNIT_WEEK => {
            let mut wds: Vec<i64> = rr
                .get("of")
                .and_then(Value::as_array)
                .map(|a| a.iter().filter_map(|o| o.get("wd").and_then(Value::as_i64)).collect())
                .unwrap_or_default();
            if wds.len() <= 1 {
                return current.checked_add_signed(Duration::days(7 * fa));
            }
            wds.sort_unstable();
            let cur = current.weekday().num_days_from_sunday() as i64;
            if let Some(next) = wds.iter().find(|w| **w > cur) {
                return current.checked_add_signed(Duration::days(next - cur));
            }
            current.checked_add_signed(Duration::days(7 * fa - cur + wds[0]))
        }
        UNIT_MONTH => current.checked_add_months(Months::new(fa as u32)),
        UNIT_YEAR => current.checked_add_months(Months::new(12 * fa as u32)),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn d(y: i32, m: u32, day: u32) -> NaiveDate {
        NaiveDate::from_ymd_opt(y, m, day).unwrap()
    }

    #[test]
    fn builds_rules_like_the_reference_mcp() {
        let r = build_rule(&RepeatSpec { unit: RepeatUnit::Day, interval: 1, weekdays: vec![], month_day: None }, d(2026, 2, 10)).unwrap();
        assert_eq!(r["fu"], 16);
        assert_eq!(r["fa"], 1);
        assert_eq!(r["of"], json!([{"dy":0}]));
        assert_eq!(r["ed"], NEVER_ENDS);
        assert_eq!(r["ia"], 1770681600);
        assert_eq!(r["rrv"], 4);
        let w = build_rule(&RepeatSpec { unit: RepeatUnit::Week, interval: 2, weekdays: vec![3, 1, 3], month_day: None }, d(2026, 2, 10))
            .unwrap();
        assert_eq!(w["of"], json!([{"wd":1},{"wd":3}]));
        let m = build_rule(&RepeatSpec { unit: RepeatUnit::Month, interval: 1, weekdays: vec![], month_day: Some(15) }, d(2026, 2, 10))
            .unwrap();
        assert_eq!(m["of"], json!([{"dy":14}]));
        assert!(build_rule(&RepeatSpec { unit: RepeatUnit::Month, interval: 1, weekdays: vec![], month_day: Some(40) }, d(2026, 2, 10))
            .is_err());
        assert!(build_rule(&RepeatSpec { unit: RepeatUnit::Day, interval: 0, weekdays: vec![], month_day: None }, d(2026, 2, 10)).is_err());
    }

    #[test]
    fn describes_rules() {
        let base = |extra: Value| {
            let mut v = json!({"rrv":4,"tp":0,"rc":0,"ed":NEVER_ENDS,"fa":1});
            for (k, val) in extra.as_object().unwrap() {
                v[k] = val.clone();
            }
            v
        };
        assert_eq!(describe(&base(json!({"fu":16,"of":[{"dy":0}]}))), "Daily");
        assert_eq!(describe(&base(json!({"fu":256,"fa":2,"of":[{"wd":1},{"wd":3}]}))), "Every 2 weeks on Mon, Wed");
        assert_eq!(describe(&base(json!({"fu":8,"of":[{"dy":-1}]}))), "Monthly on the last day");
        assert_eq!(describe(&base(json!({"fu":8,"of":[{"dy":21}]}))), "Monthly on the 22nd");
        assert_eq!(describe(&base(json!({"fu":8,"of":[{"wd":2,"wdo":2}]}))), "Monthly on 2nd Tue");
        assert_eq!(describe(&base(json!({"fu":4,"of":[{"dy":24,"mo":11}]}))), "Yearly on Dec 25");
        assert_eq!(describe(&base(json!({"fu":16,"fa":3,"tp":1}))), "3 days after completion");
        assert_eq!(describe(&base(json!({"fu":16,"rc":5}))), "Daily, 5 times");
        assert_eq!(describe(&json!({"fu":99})), "Repeating");
    }

    #[test]
    fn computes_next_occurrence() {
        let daily = json!({"fu":16,"fa":2});
        assert_eq!(next_after(&daily, d(2026, 2, 10)), Some(d(2026, 2, 12)));
        // 2026-02-10 is a Tuesday (2). Mon/Wed/Fri → Wednesday.
        let mwf = json!({"fu":256,"fa":1,"of":[{"wd":1},{"wd":3},{"wd":5}]});
        assert_eq!(next_after(&mwf, d(2026, 2, 10)), Some(d(2026, 2, 11)));
        assert_eq!(next_after(&mwf, d(2026, 2, 13)), Some(d(2026, 2, 16)));
        let monthly = json!({"fu":8,"fa":1});
        assert_eq!(next_after(&monthly, d(2026, 1, 31)), Some(d(2026, 2, 28)));
        assert_eq!(next_after(&json!({"fu":4,"fa":1}), d(2026, 2, 10)), Some(d(2027, 2, 10)));
    }
}
